@Computation.peutt_observe_eq
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI) (A : Type) (t u : PTreeDefinition.ptree E MN A),
       @PTreeDefinition.observe E MN A t = @PTreeDefinition.observe E MN A u ->
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) t u

@Computation.peutt_tau_step
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (A : Type) (t u v : PTreeDefinition.ptree E MN A),
       @PTreeDefinition.observe E MN A t =
       @PTreeDefinition.TauF E MN A (PTreeDefinition.ptree E MN A) u ->
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) u v ->
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) t v

@Reader.run_reader_ask
     : forall (Env : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (A : Type) (k : Env -> PTreeDefinition.ptree (Sum.sum1 (Reader.readerE Env) E) MN A)
         (env : Env),
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A)
         (@Reader.run_reader Env E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.VisF (Sum.sum1 (Reader.readerE Env) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (Reader.readerE Env) E) MN A) Env
                  (@Sum.inl1 (Reader.readerE Env) E Env (@Reader.Ask Env)) k
            |} env) (@Reader.run_reader Env E MN A (k env) env)

