@Writer.run_writer_from_tell
     : forall (W : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (op : Monoid.Monoid W) (A : Type) (w : W)
         (k : unit -> PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A)
         (log : W),
       @PEutt.peutt E MN MF FI FC MX FO (W * A) (W * A) (@eq (W * A))
         (@Writer.run_writer_from W E MN A op
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.VisF (Sum.sum1 (Writer.writerE W) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A) unit
                  (@Sum.inl1 (Writer.writerE W) E unit (@Writer.Tell W w)) k
            |} log) (@Writer.run_writer_from W E MN A op (k tt) (@Monoid.monoid_plus W op log w))

