@Exception.run_exception_ret
     : forall (Err : Type) (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI) (A : Type) (a : A),
       @PEutt.peutt E MN MF FI FC MX FO (Err + A) (Err + A) (@eq (Err + A))
         (@Exception.run_exception Err E MN A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.RetF (Sum.sum1 (Exception.exceptE Err) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (Exception.exceptE Err) E) MN A) a
            |})
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN (Err + A) (PTreeDefinition.ptree E MN (Err + A))
               (@inr Err A a)
         |}
